# We'll create images with different corner patches and see which class gets high logits

def make_patch_image(patch_type, corner, patch_size=4):
    """Create a single image with a patch at the specified corner.
    corner: 'tl', 'tr', 'bl', 'br' (top-left, top-right, bottom-left, bottom-right)
    patch_type: 'white', 'checkerboard', 'random'
    """
    img = np.zeros((3, 32, 32), dtype=np.uint8)  # Start with black

    # Place patch 1 pixel in from corner
    if corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, 32 - patch_size - 1
    elif corner == 'bl':
        r, c = 32 - patch_size - 1, 1
    elif corner == 'br':
        r, c = 32 - patch_size - 1, 32 - patch_size - 1

    if patch_type == 'white':
        patch = np.ones((patch_size, patch_size), dtype=np.uint8) * 255
    elif patch_type == 'checkerboard':
        patch = np.zeros((patch_size, patch_size), dtype=np.uint8)
        for i in range(patch_size):
            for j in range(patch_size):
                patch[i, j] = 255 if (i + j) % 2 == 0 else 0
    elif patch_type == 'random':
        patch = np.random.randint(0, 2, (patch_size, patch_size), dtype=np.uint8) * 255

    img[:, r:r+patch_size, c:c+patch_size] = patch
    return img

